import{_ as t,o,c as r,aj as n}from"./chunks/framework.C6uXqnaX.js";const h=JSON.parse('{"title":"JSONP support in HttpClient configuration","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"errors/NG02800.md","filePath":"errors/NG02800.md"}'),i={name:"errors/NG02800.md"};function a(p,e,d,s,c,u){return o(),r("div",null,e[0]||(e[0]=[n('<h1 id="jsonp-support-in-httpclient-configuration" tabindex="-1">JSONP support in HttpClient configuration <a class="header-anchor" href="#jsonp-support-in-httpclient-configuration" aria-label="Permalink to &quot;JSONP support in HttpClient configuration&quot;">​</a></h1><p>Angular produces this error when you attempt a <code>JSONP</code> request without providing the necessary support for it in the <code>HttpClient</code> configuration. To enable <code>JSONP</code> support, you can do one of the following:</p><ul><li>add the <code>withJsonpSupport()</code> as an argument during the <code>provideHttpClient</code> function call (e.g. <code>provideHttpClient(withJsonpSupport())</code>) when <code>bootstrapApplication</code> is useddocs</li><li>import the <code>HttpClientJsonpModule</code> in your root AppModule, when NgModule-based bootstrap is used.</li></ul><h2 id="debugging-the-error" tabindex="-1">Debugging the error <a class="header-anchor" href="#debugging-the-error" aria-label="Permalink to &quot;Debugging the error&quot;">​</a></h2><p>Make sure that the JSONP support is added into your application either by calling the <code>withJsonpSupport</code> function (when <code>provideHttpClient</code> is used) or importing the <code>HttpClientJsonpModule</code> module as described above.</p>',5)]))}const g=t(i,[["render",a]]);export{h as __pageData,g as default};
